using System.Collections.Concurrent;
using System.IdentityModel.Tokens.Jwt;
using System.Net;
using System.Security.Claims;
using System.Text;
using LifeVerse.Api.Data;
using LifeVerse.Api.Modules.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;

namespace LifeVerse.Api.Modules.Social;

public sealed record MessageRequest(string Content, Guid? RecipientUserId, Guid? GroupId, Guid? IslandId, string? ClientMessageId = null);
public sealed record PresenceRequest(string Status, string? PrivacyJson = null);
public sealed record FriendshipRequest(Guid UserId);
public sealed record GroupRequest(string Name, string Description, string? ImageUrl);
public sealed record GroupInviteRequest(Guid UserId);
public sealed record GroupRoleRequest(string Role);
public sealed record ReportRequest(Guid? ReportedUserId, Guid? MessageId, Guid? IslandId, string Reason);
public sealed record RadioRequest(string Name, string StreamUrl, float Volume = 1f, float Range = 30f, bool IsPlaying = false);
public sealed record VoicePreferencesRequest(bool PushToTalk, bool VoiceActivation, float Sensitivity, float OutputVolume, string? InputDevice, string? OutputDevice);

public static class SocialEndpoints
{
    private static readonly ConcurrentDictionary<Guid, Queue<DateTimeOffset>> MessageWindows = new();
    public static IEndpointRouteBuilder MapSocialEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var social = endpoints.MapGroup("/api/v1/social").WithTags("Social").RequireAuthorization();
        social.MapGet("/messages", ListMessagesAsync);
        social.MapPost("/messages", SendMessageAsync);
        social.MapPost("/messages/{messageId:guid}/read", MarkReadAsync);
        social.MapGet("/presence/{userId:guid}", PresenceAsync);
        social.MapPut("/presence", UpdatePresenceAsync);
        social.MapPost("/blocks/{userId:guid}", BlockAsync);
        social.MapDelete("/blocks/{userId:guid}", UnblockAsync);
        social.MapGet("/friends", FriendsAsync);
        social.MapPost("/friends/requests", FriendRequestAsync);
        social.MapPost("/friends/{userId:guid}/accept", AcceptFriendAsync);
        social.MapDelete("/friends/{userId:guid}", RemoveFriendAsync);
        social.MapPost("/groups", CreateGroupAsync);
        social.MapGet("/groups/{groupId:guid}", GetGroupAsync);
        social.MapPost("/groups/{groupId:guid}/invites", InviteAsync);
        social.MapPost("/groups/{groupId:guid}/members/{userId:guid}/role", RoleAsync);
        social.MapPost("/reports", ReportAsync);
        var voice = endpoints.MapGroup("/api/v1/voice").WithTags("Voice").RequireAuthorization();
        voice.MapPost("/rooms/{roomName}/token", VoiceTokenAsync);
        voice.MapGet("/preferences", VoicePreferencesAsync); voice.MapPut("/preferences", UpdateVoicePreferencesAsync);
        var radio = endpoints.MapGroup("/api/v1/worlds/{islandId:guid}/radios").WithTags("Radio").RequireAuthorization();
        radio.MapGet("", ListRadiosAsync); radio.MapPost("", CreateRadioAsync); radio.MapPut("/{radioId:guid}", UpdateRadioAsync); radio.MapDelete("/{radioId:guid}", DeleteRadioAsync);
        return endpoints;
    }

    private static async Task<IResult> ListMessagesAsync(string? channel, Guid? conversationWith, Guid? groupId, int page, int pageSize, HttpContext context, LifeVerseDbContext db, CancellationToken ct)
    { if (!User(context, out var me)) return Results.Unauthorized(); page = Math.Max(1, page); pageSize = Math.Clamp(pageSize == 0 ? 50 : pageSize, 1, 100); var q = db.SocialMessages.AsNoTracking().Where(x => x.DeletedAt == null); if (channel == "private" && conversationWith is not null) q = q.Where(x => x.Channel == "private" && ((x.SenderUserId == me && x.RecipientUserId == conversationWith) || (x.SenderUserId == conversationWith && x.RecipientUserId == me))); else if (groupId is not null) q = q.Where(x => x.Channel == "group" && x.GroupId == groupId); else q = q.Where(x => x.Channel == (channel ?? "global")); var total = await q.CountAsync(ct); return Results.Ok(new { page, pageSize, total, items = await q.OrderByDescending(x => x.CreatedAt).Skip((page - 1) * pageSize).Take(pageSize).OrderBy(x => x.CreatedAt).ToListAsync(ct) }); }
    private static async Task<IResult> SendMessageAsync(MessageRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct)
    { if (!User(context, out var me)) return Results.Unauthorized(); var content = new string((request.Content ?? string.Empty).Trim().Where(c => !char.IsControl(c)).Take(2000).ToArray()); if (content.Length == 0) return Results.BadRequest(); if (!Acquire(me)) return Results.StatusCode(429); if (request.ClientMessageId?.Length > 96) return Results.BadRequest(); if (request.ClientMessageId is not null) { var duplicate = await db.SocialMessages.AsNoTracking().SingleOrDefaultAsync(x => x.SenderUserId == me && x.ClientMessageId == request.ClientMessageId, ct); if (duplicate is not null) return Results.Ok(duplicate); } if (request.RecipientUserId == me || request.GroupId is not null && !await db.GroupMembers.AnyAsync(x => x.GroupId == request.GroupId && x.UserId == me, ct)) return Results.Forbid(); if (request.RecipientUserId is not null && await db.UserBlocks.AnyAsync(x => (x.UserId == me && x.BlockedUserId == request.RecipientUserId) || (x.UserId == request.RecipientUserId && x.BlockedUserId == me), ct)) return Results.Forbid(); var channel = request.GroupId is not null ? "group" : request.RecipientUserId is not null ? "private" : request.IslandId is not null ? "local" : "global"; var item = new SocialMessage { Id = Guid.NewGuid(), Channel = channel, SenderUserId = me, RecipientUserId = request.RecipientUserId, GroupId = request.GroupId, IslandId = request.IslandId, ClientMessageId = request.ClientMessageId, Content = content, CreatedAt = clock.GetUtcNow() }; db.SocialMessages.Add(item); await db.SaveChangesAsync(ct); return Results.Ok(item); }
    private static async Task<IResult> MarkReadAsync(Guid messageId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.SocialMessages.SingleOrDefaultAsync(x => x.Id == messageId && x.RecipientUserId == me && x.DeletedAt == null, ct); if (item is null) return Results.NotFound(); item.ReadAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> PresenceAsync(Guid userId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var user = await db.Users.AsNoTracking().SingleOrDefaultAsync(x => x.Id == userId && x.DeletedAt == null, ct); if (user is null) return Results.NotFound(); if (user.Id != me && user.PrivacyJson.Contains("\"presence\":\"private\"")) return Results.Ok(new { userId, status = "offline" }); return Results.Ok(new { userId, status = user.PresenceStatus, updatedAt = user.PresenceUpdatedAt }); }
    private static async Task<IResult> UpdatePresenceAsync(PresenceRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (request.Status is not ("online" or "offline" or "away" or "busy" or "invisible")) return Results.BadRequest(); var user = await db.Users.SingleAsync(x => x.Id == me, ct); user.PresenceStatus = request.Status; user.PresenceUpdatedAt = clock.GetUtcNow(); if (request.PrivacyJson is not null && request.PrivacyJson.Length <= 2048) user.PrivacyJson = request.PrivacyJson; await db.SaveChangesAsync(ct); return Results.Ok(new { status = user.PresenceStatus, updatedAt = user.PresenceUpdatedAt }); }
    private static async Task<IResult> BlockAsync(Guid userId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me) || me == userId) return Results.BadRequest(); if (!await db.Users.AnyAsync(x => x.Id == userId && x.DeletedAt == null, ct)) return Results.NotFound(); if (!await db.UserBlocks.AnyAsync(x => x.UserId == me && x.BlockedUserId == userId, ct)) { db.UserBlocks.Add(new UserBlock { Id = Guid.NewGuid(), UserId = me, BlockedUserId = userId, CreatedAt = clock.GetUtcNow() }); await db.SaveChangesAsync(ct); } return Results.NoContent(); }
    private static async Task<IResult> UnblockAsync(Guid userId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.UserBlocks.SingleOrDefaultAsync(x => x.UserId == me && x.BlockedUserId == userId, ct); if (item is not null) { db.UserBlocks.Remove(item); await db.SaveChangesAsync(ct); } return Results.NoContent(); }
    private static async Task<IResult> FriendsAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); return Results.Ok(await db.Friendships.Where(x => x.UserId == me && x.Status == "accepted").Join(db.Users, x => x.FriendUserId, x => x.Id, (x, u) => new { u.Id, u.Username }).ToListAsync(ct)); }
    private static async Task<IResult> FriendRequestAsync(FriendshipRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me) || me == request.UserId) return Results.BadRequest(); if (!await db.Users.AnyAsync(x => x.Id == request.UserId && x.DeletedAt == null, ct)) return Results.NotFound(); var existing = await db.Friendships.SingleOrDefaultAsync(x => x.UserId == me && x.FriendUserId == request.UserId, ct); if (existing is null) { var now = clock.GetUtcNow(); db.Friendships.Add(new Friendship { Id = Guid.NewGuid(), UserId = me, FriendUserId = request.UserId, Status = "pending", CreatedAt = now, UpdatedAt = now }); await db.SaveChangesAsync(ct); } return Results.Accepted(); }
    private static async Task<IResult> AcceptFriendAsync(Guid userId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var pending = await db.Friendships.SingleOrDefaultAsync(x => x.UserId == userId && x.FriendUserId == me && x.Status == "pending", ct); if (pending is null) return Results.NotFound(); pending.Status = "accepted"; pending.UpdatedAt = clock.GetUtcNow(); db.Friendships.Add(new Friendship { Id = Guid.NewGuid(), UserId = me, FriendUserId = userId, Status = "accepted", CreatedAt = pending.CreatedAt, UpdatedAt = pending.UpdatedAt }); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> RemoveFriendAsync(Guid userId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var rows = await db.Friendships.Where(x => (x.UserId == me && x.FriendUserId == userId) || (x.UserId == userId && x.FriendUserId == me)).ToListAsync(ct); db.Friendships.RemoveRange(rows); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> CreateGroupAsync(GroupRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (request.Name.Trim().Length is < 1 or > 120) return Results.BadRequest(); var now = clock.GetUtcNow(); var group = new SocialGroup { Id = Guid.NewGuid(), OwnerUserId = me, Name = request.Name.Trim(), Description = request.Description[..Math.Min(2000, request.Description.Length)], ImageUrl = request.ImageUrl, CreatedAt = now, UpdatedAt = now }; db.SocialGroups.Add(group); db.GroupMembers.Add(new GroupMember { Id = Guid.NewGuid(), GroupId = group.Id, UserId = me, Role = "owner", JoinedAt = now }); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/social/groups/{group.Id}", group); }
    private static async Task<IResult> GetGroupAsync(Guid groupId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me) || !await db.GroupMembers.AnyAsync(x => x.GroupId == groupId && x.UserId == me, ct)) return Results.Forbid(); return Results.Ok(new { group = await db.SocialGroups.AsNoTracking().SingleOrDefaultAsync(x => x.Id == groupId && x.DeletedAt == null, ct), members = await db.GroupMembers.AsNoTracking().Where(x => x.GroupId == groupId).Join(db.Users, x => x.UserId, x => x.Id, (x, u) => new { x.UserId, u.Username, x.Role }).ToListAsync(ct) }); }
    private static async Task<IResult> InviteAsync(Guid groupId, GroupInviteRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me) || !await db.GroupMembers.AnyAsync(x => x.GroupId == groupId && x.UserId == me && (x.Role == "owner" || x.Role == "admin"), ct)) return Results.Forbid(); db.GroupInvites.Add(new GroupInvite { Id = Guid.NewGuid(), GroupId = groupId, InvitedUserId = request.UserId, InvitedByUserId = me, Status = "pending", CreatedAt = clock.GetUtcNow() }); await db.SaveChangesAsync(ct); return Results.Accepted(); }
    private static async Task<IResult> RoleAsync(Guid groupId, Guid userId, GroupRoleRequest request, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me) || !await db.GroupMembers.AnyAsync(x => x.GroupId == groupId && x.UserId == me && x.Role == "owner", ct)) return Results.Forbid(); var member = await db.GroupMembers.SingleOrDefaultAsync(x => x.GroupId == groupId && x.UserId == userId, ct); if (member is null || request.Role is not ("admin" or "moderator" or "member")) return Results.BadRequest(); member.Role = request.Role; await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> ReportAsync(ReportRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (request.Reason.Trim().Length is < 3 or > 1000) return Results.BadRequest(); db.SocialReports.Add(new SocialReport { Id = Guid.NewGuid(), ReporterUserId = me, ReportedUserId = request.ReportedUserId, MessageId = request.MessageId, IslandId = request.IslandId, Reason = request.Reason.Trim(), Status = "open", CreatedAt = clock.GetUtcNow() }); await db.SaveChangesAsync(ct); return Results.Accepted(); }
    private static async Task<IResult> VoiceTokenAsync(string roomName, HttpContext context, JwtOptions jwt, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me) || roomName.Length is < 1 or > 100 || roomName.Contains('/') || roomName.Contains(' ') || roomName.Any(c => !char.IsLetterOrDigit(c) && c is not ('-' or '_' or ':'))) return Results.BadRequest(); if (roomName.StartsWith("island:", StringComparison.Ordinal) && Guid.TryParse(roomName[7..], out var islandId) && !await db.Islands.AnyAsync(x => x.Id == islandId && x.DeletedAt == null && (x.IsPublic || x.OwnerUserId == me || db.IslandPermissions.Any(p => p.IslandId == islandId && p.UserId == me && p.RevokedAt == null && p.Permission == "enter")), ct)) return Results.Forbid(); var descriptor = new SecurityTokenDescriptor { Subject = new ClaimsIdentity([new Claim(JwtRegisteredClaimNames.Sub, me.ToString()), new Claim("room", roomName), new Claim("can_publish", "true"), new Claim("can_subscribe", "true")]), Issuer = jwt.Issuer, Audience = "livekit", Expires = DateTime.UtcNow.AddMinutes(5), SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt.SigningKey)), SecurityAlgorithms.HmacSha256) }; var token = new JwtSecurityTokenHandler().CreateEncodedJwt(descriptor); return Results.Ok(new { token, room = roomName, expiresInSeconds = 300, spatialAudio = true }); }
    private static async Task<IResult> VoicePreferencesAsync(HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var user = await db.Users.AsNoTracking().SingleAsync(x => x.Id == me, ct); return Results.Ok(new { settings = user.VoiceSettingsJson }); }
    private static async Task<IResult> UpdateVoicePreferencesAsync(VoicePreferencesRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (request.Sensitivity is < 0 or > 1 || request.OutputVolume is < 0 or > 1 || (request.InputDevice?.Length > 160) || (request.OutputDevice?.Length > 160)) return Results.BadRequest(); var user = await db.Users.SingleAsync(x => x.Id == me, ct); user.VoiceSettingsJson = System.Text.Json.JsonSerializer.Serialize(new { request.PushToTalk, request.VoiceActivation, sensitivity = request.Sensitivity, outputVolume = request.OutputVolume, inputDevice = request.InputDevice, outputDevice = request.OutputDevice, updatedAt = clock.GetUtcNow() }); await db.SaveChangesAsync(ct); return Results.Ok(new { settings = user.VoiceSettingsJson }); }
    private static async Task<IResult> ListRadiosAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out _)) return Results.Unauthorized(); return Results.Ok(await db.RadioStations.AsNoTracking().Where(x => x.IslandId == islandId).ToListAsync(ct)); }
    private static async Task<IResult> CreateRadioAsync(Guid islandId, RadioRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me) || !await db.Islands.AnyAsync(x => x.Id == islandId && x.OwnerUserId == me && x.DeletedAt == null, ct)) return Results.Forbid(); if (!AllowedStream(request.StreamUrl)) return Results.BadRequest(new { error = "Only approved public HTTPS streams are allowed." }); var item = new RadioStation { Id = Guid.NewGuid(), IslandId = islandId, OwnerUserId = me, Name = request.Name.Trim()[..Math.Min(120, request.Name.Trim().Length)], StreamUrl = request.StreamUrl, Volume = Math.Clamp(request.Volume, 0, 1), Range = Math.Clamp(request.Range, 1, 200), IsPlaying = request.IsPlaying, UpdatedAt = clock.GetUtcNow() }; db.RadioStations.Add(item); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/worlds/{islandId}/radios/{item.Id}", item); }
    private static async Task<IResult> UpdateRadioAsync(Guid islandId, Guid radioId, RadioRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.RadioStations.SingleOrDefaultAsync(x => x.Id == radioId && x.IslandId == islandId, ct); if (item is null) return Results.NotFound(); var allowed = item.OwnerUserId == me || await db.IslandPermissions.AnyAsync(x => x.IslandId == islandId && x.UserId == me && x.RevokedAt == null && (x.Permission == "edit" || x.Permission == "admin"), ct); if (!allowed) return Results.Forbid(); if (!AllowedStream(request.StreamUrl)) return Results.BadRequest(); item.Name = request.Name.Trim()[..Math.Min(120, request.Name.Trim().Length)]; item.StreamUrl = request.StreamUrl; item.Volume = Math.Clamp(request.Volume, 0, 1); item.Range = Math.Clamp(request.Range, 1, 200); item.IsPlaying = request.IsPlaying; item.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(item); }
    private static async Task<IResult> DeleteRadioAsync(Guid islandId, Guid radioId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var item = await db.RadioStations.SingleOrDefaultAsync(x => x.Id == radioId && x.IslandId == islandId && x.OwnerUserId == me, ct); if (item is null) return Results.NotFound(); db.RadioStations.Remove(item); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static bool User(HttpContext context, out Guid id) => Guid.TryParse(context.User.FindFirstValue(JwtRegisteredClaimNames.Sub), out id);
    private static bool Acquire(Guid user) { var q = MessageWindows.GetOrAdd(user, _ => new Queue<DateTimeOffset>()); lock (q) { var now = DateTimeOffset.UtcNow; while (q.Count > 0 && now - q.Peek() > TimeSpan.FromSeconds(10)) q.Dequeue(); if (q.Count >= 20) return false; q.Enqueue(now); return true; } }
    private static bool AllowedStream(string value) { if (!Uri.TryCreate(value, UriKind.Absolute, out var uri) || uri.Scheme != Uri.UriSchemeHttps || uri.UserInfo.Length > 0) return false; var host = uri.Host.ToLowerInvariant(); if (host is "localhost" or "postgres" or "redis" or "minio" || host.EndsWith(".internal") || host.EndsWith(".local") || IPAddress.TryParse(host, out var ip) && (IPAddress.IsLoopback(ip) || ip.IsIPv6LinkLocal || ip.ToString().StartsWith("10.") || ip.ToString().StartsWith("192.168.") || ip.ToString().StartsWith("172."))) return false; return host.Length <= 255; }
}
